SELECT flowtag, successpct, errtally, rtrytally, 
    ROUND(CAST((successpct / CAST(errtally + 1 AS numeric)) * (1 - CAST(rtrytally AS numeric) / (errtally + 1)) AS numeric), 2) AS df rs
FROM dataflow LIMIT 5;

SELECT flowtag, successpct, errtally, rtrytally, 
    ROUND(CAST((successpct / CAST(errtally + 1 AS numeric)) * (1 - CAST(rtrytally AS numeric) / (errtally + 1)) AS numeric), 2) AS dfrs
FROM dataflow LIMIT 5;
